#include <atomic>
#include <iostream>

int main() {
    std::atomic<int> stock{20};
    std::cout << stock.fetch_add(5) << " -> " << stock.load() << "\n";
    std::cout << stock.fetch_sub(3) << " -> " << stock.load() << "\n";
    stock += 2;
    stock -= 4;
    ++stock;
    --stock;
    std::cout << stock.load() << "\n";
}
